def priority(task, state, w_slack=1.0, w_wspt=0.5, tier_boost=2.0, late_boost=5.0):
    slack = task.due - state.now - task.estimated_runtime
    tier = tier_boost if task.tenant == 'premium' else 1.0
    wspt = task.weight / max(task.estimated_runtime, 1e-6)
    late = late_boost * max(0.0, -slack) / max(state.mean_est, 1e-6)
    return tier * (-w_slack * slack + w_wspt * wspt + late)

def priority(task, state, w_slack=1.0, w_wspt=0.3, tier_boost=2.0, pressure_scale=1.0):
    slack = task.due - state.now - task.estimated_runtime
    tier = tier_boost if task.tenant == 'premium' else 1.0
    pressure = 1.0 + min(1.0, pressure_scale * state.queue_work / max(state.capacity, 1e-6))
    wspt = task.weight / max(task.estimated_runtime, 1e-6)
    return tier * (-w_slack * slack * pressure + w_wspt * wspt)

