def priority(task, state, k=1.0, m=2.0, guard=2.0):
    slack = task.due - task.estimated_runtime - state.now
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / max(task.estimated_runtime, 1e-6)
    if slack <= 0:
        return base * guard
    return base * math.exp(-slack / (k * max(state.mean_est, 1e-6)))

import math
def priority(task, state, k=2.5, m=2.0, p=1.5, g=1.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - est - state.now
    wait = state.now - task.release
    tier = m if task.tenant == 'premium' else 1.0
    base = tier * task.weight / est
    # power-law urgency on normalized slack
    norm = slack / max(k * state.mean_est, 1e-6)
    if norm <= 0:
        urg = (1.0 - norm) ** p
    else:
        urg = 1.0 / (1.0 + norm) ** p
    # separate overdue hard boost and aging
    if slack <= 0:
        boost = 1.0 + g * (-slack) / est
    else:
        boost = 1.0
    age = 1.0 + wait / max(est, 1e-6)
    return base * urg * boost * math.log1p(age)

