def priority(task, state, k=1.0, guard=2.0, boost=5.0):
    slack = task.due - task.estimated_runtime - state.now
    # ATC-like urgency
    base = task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))
    # lateness / near-late guard
    if slack <= 0:
        base += boost / max(task.estimated_runtime, 1e-6)
    elif slack < guard * max(task.estimated_runtime, 1e-6):
        base += (guard - slack / max(task.estimated_runtime, 1e-6)) / max(state.mean_est, 1e-6)
    # premium tier bump
    if task.tenant == 'premium':
        base *= 1.0 + 0.5 * (1.0 if slack <= 0 else 0.0)
    return base

