    if pressure > qthresh:
        return tier / max(task.estimated_runtime, 1e-6) + (1e3 if slack < 0 else 0.0)
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))

