def priority(task, state, k=0.5, m=2.0, type_bonus=1.2, type_penalty=0.9):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'reduce':
        tb = type_bonus
    elif task.task_type == 'other':
        tb = type_penalty
    else:
        tb = 1.0
    atc = tier * tb * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    # Under high load, defer low-priority 'other' work
    load = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    if load > 1.0 and task.task_type == 'other':
        return atc / (1.0 + load)
    return atc

