def priority(task, state, m=2.0, k=0.5, a=1.0, b=0.5):
    # Hybrid: WSPT base scaled by tenant tier and waiting-time aging, plus
    # ATC slack term. Switch to lateness-first when tasks are already late.
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wait = max(0.0, state.now - task.release)
    slack = max(0.0, task.due - est - state.now)
    atc = task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    wspt_age = task.weight / est * (1.0 + b * wait / est)
    lateness = max(0.0, state.now + est - task.due)
    if lateness > 0:
        return tier * (1e3 + a * task.weight * lateness / est)
    return tier * (atc + wspt_age)

def priority(task, state, k=0.5, m=2.0, b=1.0):
    # Due-date (MOD) base with a lateness-escalation term. Tasks already late
    # get a large boost proportional to their weighted lateness; otherwise
    # MOD ordering with premium tenant tier applied to the urgency.
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    lateness = max(0.0, state.now + est - task.due)
    if lateness > 0:
        return 1e6 * tier * task.weight + b * task.weight * lateness / est
    return tier * (state.capacity + 1.0) - max(task.due, state.now + est)

