def priority(task, state, k=0.5, m=2.0, q_thresh=4.0, slow_k=1.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    queue_pressure = state.queue_work / max(state.capacity, 1e-6)
    k_eff = k if queue_pressure < q_thresh else k * slow_k
    return tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k_eff * max(state.mean_est, 1e-6)))

def priority(task, state, k=0.5, m=2.0, slack_floor=-0.5, urgent_boost=3.0):
    raw_slack = task.due - task.estimated_runtime - state.now
    slack = max(slack_floor * max(state.mean_est, 1e-6), raw_slack)
    tier = m if task.tenant == 'premium' else 1.0
    boost = urgent_boost if raw_slack < 0 else 1.0
    return tier * boost * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))

